#!/usr/bin/env python3
"""Build the DCS HQ HTML module — Wing hub + .miz engine + Mission JSON (P2)."""

import json
import os
import base64
import re

HERE = os.path.dirname(os.path.abspath(__file__))
ASSETS_PATH = os.path.join(HERE, 'assets.json')
if not os.path.isfile(ASSETS_PATH):
    raise SystemExit(f"[ERREUR] Entrée manquante : {ASSETS_PATH} (assets.json attendu à la racine du dépôt)")

APP_VERSION = "0.1.1"

with open(ASSETS_PATH) as f:
    A = json.load(f)

# ---------- DCS Engine (copie verbatim du Comm Plan Editor) ----------
# Copié depuis dcs_comm_plan_editor.html — DCS_TOKENIZER + DCS_PARSER + DCS_EXTRACTOR
# Encodé base64 pour éviter les problèmes d'échappement Python
import base64 as _b64
# ---------- Patch pipeline (copie verbatim CPE — applyPatches + retokenizeSafety + rebuildMiz) ----------
_APPLY_PATCHES    = _b64.b64decode('').decode('utf-8')
_RETOKENIZE       = _b64.b64decode('').decode('utf-8')
_REBUILD_MIZ      = _b64.b64decode('').decode('utf-8')

import base64 as _b64
_DCS_ENGINE    = _b64.b64decode('').decode('utf-8')
_DCS_EXTRACTOR = _b64.b64decode('').decode('utf-8')

# ---------- KRAFT SVG variants (identiques à Recon Station / BG) ----------
def _kraft_variant(b64svg, bg_color, grain_color):
    svg_bytes = base64.b64decode(b64svg)
    svg_str = svg_bytes.decode('utf-8')
    svg_str = svg_str.replace('#d6c7a3', bg_color).replace('#ccbe99', grain_color)
    return base64.b64encode(svg_str.encode('utf-8')).decode('ascii')

KRAFT_NATO  = _kraft_variant(A['KRAFT_SVG'], '#d6c7a3', '#ccbe99')
KRAFT_SOV   = _kraft_variant(A['KRAFT_SVG'], '#d4c075', '#c8b060')
KRAFT_MNATO = _kraft_variant(A['KRAFT_SVG'], '#e4dfd2', '#d8d4c8')
KRAFT_MEAST = _kraft_variant(A['KRAFT_SVG'], '#c8c1b2', '#bcb5a6')

# ---------- Generic SVG logos (identiques à BG) ----------
